insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','A guest''s reservation can''t be found at check-in. Best first step?','No encuentras la reservación del huésped al llegar. ¿Primer paso?','["Ask for the confirmation number and search by name, dates and third-party site", "Send them to another hotel right away", "Tell them they don''t have one", "Charge walk-in rate without checking"]'::jsonb,'["Pedir el número de confirmación y buscar por nombre, fechas y sitio externo", "Mandarlo a otro hotel de inmediato", "Decirle que no tiene", "Cobrar tarifa de mostrador sin revisar"]'::jsonb,0,'Most ''lost'' reservations are under a different name, date or a third-party booking.','La mayoría están con otro nombre, fecha o en un sitio externo.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['recovery','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','The hotel is oversold and you must ''walk'' a guest with a confirmed reservation. What''s standard good practice?','El hotel está sobrevendido y debes reubicar a un huésped con reservación. ¿Buena práctica?','["Apologize, book a comparable nearby hotel, cover the first night and transport", "Tell them to find a room themselves", "Put them in an out-of-order room", "Ask them to wait in the lobby until a checkout"]'::jsonb,'["Disculparte, reservar un hotel cercano comparable, cubrir la primera noche y el transporte", "Decirle que busque cuarto solo", "Darle un cuarto fuera de servicio", "Que espere en el lobby a que alguien salga"]'::jsonb,0,'A courteous, paid relocation protects the guest and the hotel''s reputation; follow your GM''s walk procedure.','Una reubicación cortés y pagada protege al huésped y la reputación; sigue el procedimiento del gerente.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','hard',array['recovery','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','A guest''s key card stops working. What should you do before making a new key?','La llave del huésped dejó de funcionar. ¿Qué haces antes de hacer otra?','["Give them a master key", "Verify their ID matches the guest on the room", "Ask what room they want", "Just make one"]'::jsonb,'["Darle una llave maestra", "Verificar que su ID coincida con el huésped del cuarto", "Preguntar qué cuarto quiere", "Hacerla sin más"]'::jsonb,1,'Never issue a key without confirming identity — it protects every guest.','Nunca des una llave sin confirmar identidad; protege a todos.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','easy',array['recovery','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','A guest finds the room wasn''t what they booked (king vs. two queens). Best response?','El huésped encuentra un cuarto distinto al reservado (king vs. dos queen). ¿Mejor respuesta?','["Tell them to call the booking site", "Apologize, check availability and move them, or offer a fix if sold out", "Ignore it until tomorrow", "Say all rooms are the same"]'::jsonb,'["Que llame al sitio de reservas", "Disculparte, revisar disponibilidad y cambiarlo, o una alternativa si no hay", "Ignorarlo hasta mañana", "Decir que todos son iguales"]'::jsonb,1,'Fix it now when possible; if not, offer what you can and log it for tomorrow.','Resuélvelo ahora si se puede; si no, ofrece algo y regístralo.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['recovery','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','Who should hear about a complaint you already fixed?','¿Quién debe saber de una queja que ya resolviste?','["Only the guest", "Social media", "Nobody — it''s fixed", "Your manager and the next shift, through the log"]'::jsonb,'["Solo el huésped", "Redes sociales", "Nadie, ya está", "Tu gerente y el siguiente turno, por la bitácora"]'::jsonb,3,'Logging lets others follow up and spot repeat problems.','Registrar permite dar seguimiento y ver problemas repetidos.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['recovery','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','upsell','When is the best time to mention a paid upgrade or late checkout?','¿Cuándo es mejor ofrecer una mejora pagada o salida tarde?','["Only if they ask for a manager", "During check-in, after greeting and confirming their stay", "When they''re rushing out", "By slipping a note under the door at night"]'::jsonb,'["Solo si piden al gerente", "En el check-in, tras saludar y confirmar la estancia", "Cuando van de prisa", "Con una nota bajo la puerta en la noche"]'::jsonb,1,'Check-in is the natural moment to match offers to the guest''s needs.','El check-in es el momento natural para ofrecer según sus necesidades.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['upsell','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','upsell','A guest booked through a third-party site. Which is a good, honest enrollment pitch?','Un huésped reservó por un sitio externo. ¿Qué invitación honesta es buena?','["Explain joining the hotel''s loyalty program is free and book direct next time for member benefits", "Charge them a fee", "Refuse to check them in", "Say third-party bookings are illegal"]'::jsonb,'["Explicar que el programa de lealtad es gratis y que la próxima reserve directo para beneficios", "Cobrarle una cuota", "Negarle el check-in", "Decir que esas reservas son ilegales"]'::jsonb,0,'Keep it positive; never criticize the guest''s booking choice.','Mantenlo positivo; no critiques cómo reservó.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','easy',array['upsell','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','A guest asks to cancel a non-refundable rate. What do you do?','Un huésped quiere cancelar una tarifa no reembolsable. ¿Qué haces?','["Refund it quietly", "Change the rate type yourself", "Tell them it''s impossible and hang up", "Explain the rate rules kindly and involve a manager for any exception"]'::jsonb,'["Reembolsar a escondidas", "Cambiar la tarifa tú mismo", "Decir que es imposible y colgar", "Explicar con amabilidad las reglas y pedir al gerente cualquier excepción"]'::jsonb,3,'Exceptions are a manager decision; explain the policy with empathy.','Las excepciones las decide el gerente; explica con empatía.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['reservations','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','What should you read back before ending a reservation call?','¿Qué debes repetir antes de terminar una llamada de reservación?','["Your own schedule", "Nothing", "Name, dates, room type, rate, and cancellation policy", "Only the hotel name"]'::jsonb,'["Tu horario", "Nada", "Nombre, fechas, tipo de cuarto, tarifa y política de cancelación", "Solo el nombre del hotel"]'::jsonb,2,'A read-back catches mistakes before arrival.','Repetir los datos evita errores al llegar.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','easy',array['reservations','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','A group leader wants 10 rooms next month at a discount. What''s the right move?','Un líder de grupo quiere 10 cuartos el mes que viene con descuento. ¿Qué haces?','["Block rooms without approval", "Tell them groups aren''t allowed", "Promise any rate they want", "Take their details and pass it to the GM or sales for a group quote"]'::jsonb,'["Bloquear cuartos sin aprobación", "Decir que no se aceptan grupos", "Prometer la tarifa que pida", "Tomar sus datos y pasarlo al gerente o ventas para cotizar"]'::jsonb,3,'Group rates and blocks need manager approval.','Las tarifas y bloqueos de grupo requieren aprobación.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['reservations','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','Under Minnesota law, an innkeeper may remove a guest who:','Según la ley de Minnesota, el hotel puede sacar a un huésped que:','["Complained about the Wi-Fi", "Left a bad review", "Is disorderly or violates posted rules, after the steps the law requires", "Checked in late"]'::jsonb,'["Se quejó del Wi-Fi", "Dejó una mala reseña", "Es desordenado o viola las reglas publicadas, siguiendo los pasos de la ley", "Llegó tarde"]'::jsonb,2,'Minn. Stat. 327.73 lists when a guest can be ejected; managers handle it.','La ley 327.73 indica cuándo; lo maneja el gerente.','https://www.revisor.mn.gov/statutes/cite/327.73',array['front_desk','night_audit']::text[],'role','med',array['policy','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','A caller asks if their spouse is staying at the hotel. What do you say?','Alguien llama y pregunta si su esposo(a) está hospedado. ¿Qué dices?','["Give the room number", "Confirm and describe them", "Don''t confirm; offer to take a message or transfer without saying the room number", "Read the reservation details"]'::jsonb,'["Dar el número de cuarto", "Confirmar y describirlo", "No confirmar; ofrecer tomar un mensaje o transferir sin dar número", "Leer la reservación"]'::jsonb,2,'Guest privacy and safety come first — never confirm or give room numbers.','Primero la privacidad y seguridad: nunca confirmes ni des el número.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','easy',array['policy','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','A guest asks to have a room key made for a visitor. Policy?','Un huésped pide una llave para un visitante. ¿Política?','["Only registered guests on the folio get keys; the guest can add the person per policy with ID", "Give the visitor a master key", "Make one for anyone they name", "Leave the door propped"]'::jsonb,'["Solo huéspedes registrados reciben llave; puede agregarlo según la política con ID", "Dar llave maestra al visitante", "Hacer para quien diga", "Dejar la puerta abierta"]'::jsonb,0,'Keys go only to registered, identified guests.','Las llaves son solo para huéspedes registrados e identificados.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['policy','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','At shift change, how should two people hand off a cash drawer?','En el cambio de turno, ¿cómo se entrega una caja?','["Skip it when busy", "Count it alone after they leave", "Count it together and both sign the count", "Leave it for the next person"]'::jsonb,'["Omitirlo si hay mucho trabajo", "Contarla solo después", "Contarla juntos y firmar ambos", "Dejarla para el siguiente"]'::jsonb,2,'A joint count makes each person accountable for their shift.','Contar juntos hace a cada uno responsable de su turno.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['cash','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','A guest pays cash and wants change in large bills for a $100. Your drawer is short on 20s. Best action?','Un huésped paga en efectivo y quiere cambio de $100; te faltan billetes de 20. ¿Mejor acción?','["Give an IOU", "Use tips", "Take money from the bar drawer", "Follow your change-fund procedure with the manager — don''t borrow from other funds"]'::jsonb,'["Dar un vale", "Usar propinas", "Tomar de la caja del bar", "Seguir el procedimiento de cambio con el gerente; no tomar de otros fondos"]'::jsonb,3,'Mixing funds breaks accountability and causes variances.','Mezclar fondos rompe el control y causa diferencias.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','hard',array['cash','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','payments','A caller says they''re from the card company and asks you to read a guest''s card number. You:','Alguien dice ser de la compañía de tarjetas y pide el número de tarjeta de un huésped. Tú:','["Read only the last 8 digits", "Refuse and tell your manager — it''s a common scam", "Read it to them", "Email it"]'::jsonb,'["Leer los últimos 8 dígitos", "Negarte y avisar al gerente; es una estafa común", "Leerlo", "Mandarlo por correo"]'::jsonb,1,'Never share card data by phone; PCI rules protect it.','Nunca compartas datos de tarjetas por teléfono; PCI los protege.','https://www.pcisecuritystandards.org/standards/',array['front_desk','night_audit']::text[],'role','med',array['payments','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','payments','Where may full card numbers be written down?','¿Dónde se pueden anotar números completos de tarjeta?','["On a sticky note", "In the shift log", "On the reservation printout", "Nowhere — only in the approved payment system"]'::jsonb,'["En una nota adhesiva", "En la bitácora", "En la reservación impresa", "En ningún lado; solo en el sistema de pago aprobado"]'::jsonb,3,'PCI DSS bars storing card data outside secure systems.','PCI DSS prohibe guardar datos fuera de sistemas seguros.','https://www.pcisecuritystandards.org/standards/',array['front_desk','night_audit']::text[],'role','easy',array['payments','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Someone in the lobby asks you to let them into ''their friend''s'' room. You:','Alguien en el lobby pide que lo dejes entrar al cuarto de ''su amigo''. Tú:','["Politely refuse and offer to call the room", "Let them in", "Give a key if they know the room number", "Ask housekeeping to open it"]'::jsonb,'["Negarte con cortesía y ofrecer llamar al cuarto", "Dejarlo entrar", "Dar llave si sabe el número", "Pedir a limpieza que abra"]'::jsonb,0,'Only registered guests get access.','Solo los huéspedes registrados tienen acceso.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['security','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','You notice a guest''s door propped open late at night with nobody around. Best step?','Ves la puerta de un cuarto abierta tarde en la noche sin nadie. ¿Mejor paso?','["Call the room or knock and announce, and close it if no one answers, then log it", "Walk in and look around", "Ignore it", "Take items for safekeeping"]'::jsonb,'["Llamar o tocar y anunciarte; cerrar si nadie responde y registrarlo", "Entrar a revisar", "Ignorarlo", "Llevarte cosas para guardarlas"]'::jsonb,0,'Protect the guest without entering the room; document it.','Protege al huésped sin entrar; regístralo.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','med',array['security','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency','The power goes out at night. What''s an early priority?','Se va la luz en la noche. ¿Una prioridad?','["Leave the desk to go home", "Light candles in the halls", "Restart the PMS repeatedly", "Check elevators for trapped people and use flashlights, not candles"]'::jsonb,'["Irte a casa", "Prender velas en pasillos", "Reiniciar el sistema una y otra vez", "Revisar elevadores por personas atrapadas y usar linternas, no velas"]'::jsonb,3,'Ready.gov advises flashlights over candles; trapped riders need help first.','Ready.gov recomienda linternas en vez de velas.','https://www.ready.gov/power-outages',array['front_desk','night_audit']::text[],'role','med',array['emergency','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency','The fire alarm sounds. Which is a front desk task?','Suena la alarma de incendio. ¿Tarea de recepción?','["Silence the alarm and wait", "Use the elevator to check floors", "Follow the fire plan: call 911/check the panel, grab the in-house list, guide guests out", "Tell guests it''s probably false"]'::jsonb,'["Apagar la alarma y esperar", "Usar el elevador para revisar", "Seguir el plan: llamar al 911/revisar el panel, tomar la lista de huéspedes y guiarlos", "Decir que seguro es falsa"]'::jsonb,2,'Never assume a false alarm; the in-house list helps account for guests.','Nunca supongas falsa alarma; la lista ayuda a ubicar huéspedes.','https://www.redcross.org/get-help/how-to-prepare-for-emergencies/types-of-emergencies/fire.html',array['front_desk','night_audit']::text[],'role','hard',array['emergency','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','checkout','A guest disputes a charge on their bill at checkout. First step?','Un huésped disputa un cargo al salir. ¿Primer paso?','["Remove every charge", "Refuse to discuss", "Listen, review the folio with them, and correct or escalate per policy", "Tell them to call their bank"]'::jsonb,'["Quitar todos los cargos", "Negarte a hablar", "Escuchar, revisar el folio juntos y corregir o escalar según política", "Que llame a su banco"]'::jsonb,2,'Calm review settles most disputes before a chargeback.','Revisar con calma resuelve la mayoría antes de un contracargo.','https://www.consumerfinance.gov/ask-cfpb/what-is-a-chargeback-en-2031/',array['front_desk','night_audit']::text[],'role','easy',array['checkout','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','language','A guest speaks little English. What helps most?','Un huésped habla poco inglés. ¿Qué ayuda más?','["Hand them a long printed policy", "Speak slowly in simple words, use gestures or a translation app, and confirm understanding", "Rush through check-in", "Talk louder"]'::jsonb,'["Darle una política larga impresa", "Hablar despacio y simple, usar gestos o una app y confirmar que entendió", "Apurar el check-in", "Hablar más fuerte"]'::jsonb,1,'Simple language and tools beat volume.','Palabras simples y herramientas sirven más que gritar.','general hospitality best practice',array['front_desk','night_audit']::text[],'role','easy',array['language','front_desk','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','A reservation is still ''arriving'' at audit time. What should you check before marking it a no-show?','Una reservación sigue ''por llegar'' en la auditoría. ¿Qué revisas antes del no-show?','["Whether it''s raining", "Nothing — cancel it", "The guest''s social media", "Guarantee type, any late-arrival note, and the hotel''s no-show policy"]'::jsonb,'["Si llueve", "Nada, cancelarla", "Sus redes sociales", "Tipo de garantía, notas de llegada tarde y la política de no-show"]'::jsonb,3,'Checking avoids charging guests who are just late.','Revisar evita cobrar a quien solo viene tarde.','general hospitality best practice',array['night_audit']::text[],'role','med',array['audit','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','Rooms sold 80, rooms available 100, room revenue $8,000. What''s RevPAR?','Vendidos 80, disponibles 100, ingreso $8,000. ¿RevPAR?','["$8,000", "$100", "$64", "$80"]'::jsonb,'["$8,000", "$100", "$64", "$80"]'::jsonb,3,'RevPAR = room revenue ÷ rooms available = 8,000 ÷ 100.','RevPAR = ingreso ÷ cuartos disponibles = 8,000 ÷ 100.','general hospitality best practice',array['night_audit']::text[],'role','hard',array['audit','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','Housekeeping shows a room vacant but the system shows it occupied. This is called a:','Limpieza dice vacío pero el sistema dice ocupado. Esto se llama:','["Upgrade", "Comp", "Overbook", "Room status discrepancy — investigate before audit closes"]'::jsonb,'["Mejora", "Cortesía", "Sobreventa", "Discrepancia de estatus; investigar antes de cerrar"]'::jsonb,3,'Discrepancies can hide skips or sleepers.','Las discrepancias pueden ocultar fugas o cuartos sin cobrar.','general hospitality best practice',array['night_audit']::text[],'role','med',array['audit','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','Before you run the end-of-day close, what should you print or save?','Antes de cerrar el día, ¿qué imprimes o guardas?','["Only the weather", "Required reports such as the in-house list and arrivals in case the system goes down", "Nothing", "A guest''s card numbers"]'::jsonb,'["Solo el clima", "Reportes requeridos como lista de huéspedes y llegadas por si falla el sistema", "Nada", "Números de tarjetas"]'::jsonb,1,'Backup lists let you work if the PMS fails.','Las listas de respaldo sirven si falla el sistema.','general hospitality best practice',array['night_audit']::text[],'role','med',array['audit','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','At 3 a.m. a person with no key wanders the halls. Best response?','A las 3 a.m. alguien sin llave camina por los pasillos. ¿Mejor respuesta?','["Politely ask if you can help, verify they''re a guest, and call police if they''re a threat", "Confront them aggressively", "Lock yourself in the office and wait", "Ignore them"]'::jsonb,'["Preguntar con cortesía si puede ayudarle, verificar si es huésped y llamar a la policía si es amenaza", "Enfrentarlo agresivamente", "Encerrarte y esperar", "Ignorarlo"]'::jsonb,0,'Friendly contact deters problems; call for help when needed.','El contacto amable previene problemas; pide ayuda si hace falta.','general hospitality best practice',array['night_audit']::text[],'role','med',array['security','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Working alone overnight, how often should someone know you''re OK?','Trabajando solo de noche, ¿alguien debe saber que estás bien?','["Only if you get hurt", "Follow the hotel''s check-in plan and keep a phone with you", "Once a month", "Never"]'::jsonb,'["Solo si te lastimas", "Seguir el plan de reporte del hotel y tener un teléfono", "Una vez al mes", "Nunca"]'::jsonb,1,'Lone-worker check-ins get help fast if something happens.','Reportarse ayuda a que llegue ayuda rápido.','general hospitality best practice',array['night_audit']::text[],'role','easy',array['security','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','id','In Minnesota, which of these is valid proof of age to buy alcohol?','En Minnesota, ¿cuál es prueba válida de edad para comprar alcohol?','["A photo on their phone", "A credit card", "A valid driver''s license or state ID with photo and birth date", "A student ID"]'::jsonb,'["Una foto en el teléfono", "Una tarjeta de crédito", "Una licencia o ID estatal válida con foto y fecha de nacimiento", "Una credencial escolar"]'::jsonb,2,'Minn. Stat. 340A.503 subd. 6 lists accepted IDs.','La ley 340A.503 subd. 6 enumera las IDs aceptadas.','https://www.revisor.mn.gov/statutes/cite/340A.503',array['bartender']::text[],'role','easy',array['id','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','id','Besides a driver''s license or state ID, which ID does Minnesota law accept for alcohol?','Además de licencia o ID estatal, ¿qué ID acepta la ley de Minnesota?','["A library card", "A gym membership card", "A business card", "A valid U.S. passport or U.S. military ID"]'::jsonb,'["Tarjeta de biblioteca", "Tarjeta del gimnasio", "Tarjeta de presentación", "Pasaporte de EE. UU. o ID militar de EE. UU. válidos"]'::jsonb,3,'340A.503 subd. 6 also allows a U.S. passport, DoD military ID, and a foreign national''s valid passport.','También acepta pasaporte de EE. UU., ID militar y pasaporte de extranjeros.','https://www.revisor.mn.gov/statutes/cite/340A.503',array['bartender']::text[],'role','med',array['id','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','id','A guest turns 21 today. When can you legally serve them in Minnesota?','Un huésped cumple 21 hoy. ¿Desde cuándo puedes servirle?','["Noon", "8:00 a.m. on their 21st birthday", "Midnight", "Only tomorrow"]'::jsonb,'["Mediodía", "8:00 a.m. del día que cumple 21", "Medianoche", "Hasta mañana"]'::jsonb,1,'340A.503 subd. 5a: a person isn''t 21 until 8 a.m. on their birthday.','340A.503 subd. 5a: no tiene 21 hasta las 8 a.m. de su cumpleaños.','https://www.revisor.mn.gov/statutes/cite/340A.503',array['bartender']::text[],'role','hard',array['id','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','id','You believe an ID is fake. What may a licensed retailer do in Minnesota?','Crees que una ID es falsa. ¿Qué puede hacer el establecimiento?','["Keep it as a souvenir", "Serve anyway", "Throw it away", "Refuse service; it may seize the ID and must give it to police within 24 hours"]'::jsonb,'["Guardarla de recuerdo", "Servir igual", "Tirarla", "Negar servicio; puede retenerla y debe entregarla a la policía en 24 horas"]'::jsonb,3,'340A.503 subd. 6(c) allows seizure with delivery to law enforcement within 24 hours.','340A.503 subd. 6(c) permite retenerla y entregarla en 24 horas.','https://www.revisor.mn.gov/statutes/cite/340A.503',array['bartender']::text[],'role','med',array['id','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','id','A 21-year-old orders two drinks; their 19-year-old friend is with them. What do you do?','Alguien de 21 pide dos tragos y su amigo de 19 está con él. ¿Qué haces?','["Serve both if they''re nice", "Serve only the of-age guest one drink and watch for passing it to the minor", "Let the 19-year-old pay", "Serve both drinks"]'::jsonb,'["Servir si son amables", "Servir solo al mayor de edad y vigilar que no se lo pase", "Que pague el de 19", "Servir ambos"]'::jsonb,1,'Furnishing alcohol to anyone under 21 is illegal under 340A.503.','Dar alcohol a menores de 21 es ilegal (340A.503).','https://www.revisor.mn.gov/statutes/cite/340A.503',array['bartender']::text[],'role','easy',array['id','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','intox','Minnesota law says you may not sell alcohol to someone who is:','La ley de Minnesota prohibe vender alcohol a alguien que está:','["Obviously intoxicated", "Paying cash", "From another state", "Wearing a hat"]'::jsonb,'["Obviamente intoxicado", "Pagando en efectivo", "De otro estado", "Con sombrero"]'::jsonb,0,'Minn. Stat. 340A.502 bans sales to obviously intoxicated persons.','La ley 340A.502 lo prohibe.','https://www.revisor.mn.gov/statutes/cite/340A.502',array['bartender']::text[],'role','med',array['intox','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','intox','Which is a common sign a guest may be intoxicated?','¿Señal común de que alguien está intoxicado?','["Asking for the menu", "Slurred speech or stumbling", "Ordering water", "Paying with a card"]'::jsonb,'["Pedir el menú", "Habla arrastrada o tropezar", "Pedir agua", "Pagar con tarjeta"]'::jsonb,1,'Watch behavior, not just drink count.','Observa la conducta, no solo cuántos tragos.','general hospitality best practice',array['bartender']::text[],'role','med',array['intox','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','intox','Why does refusing an obviously drunk guest matter beyond the law?','¿Por qué importa negarle a alguien muy borracho, además de la ley?','["It speeds up closing", "Under dram shop law the bar can be liable for harm they cause", "It doesn''t", "It saves ice"]'::jsonb,'["Cierra más rápido", "Por la ley ''dram shop'', el bar puede ser responsable del daño que cause", "No importa", "Ahorra hielo"]'::jsonb,1,'Minn. Stat. 340A.801 lets injured people sue for illegal sales.','La ley 340A.801 permite demandar por ventas ilegales.','https://www.revisor.mn.gov/statutes/cite/340A.801',array['bartender']::text[],'role','hard',array['intox','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','intox','How should you cut off a guest?','¿Cómo dejas de servirle a alguien?','["Privately and calmly, offer water or food, and help arrange a safe ride", "By ignoring them until they leave", "By pouring weaker drinks secretly", "Loudly in front of everyone"]'::jsonb,'["En privado y con calma, ofrecer agua o comida y ayudar con transporte seguro", "Ignorándolo hasta que se vaya", "Sirviendo tragos más débiles a escondidas", "En voz alta frente a todos"]'::jsonb,0,'A calm, private cutoff reduces conflict; tell your manager.','Hacerlo en privado reduce conflictos; avisa al gerente.','general hospitality best practice',array['bartender']::text[],'role','med',array['intox','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','intox','A guest you cut off asks a friend to order for them. You:','Alguien a quien ya no sirves le pide a un amigo que pida por él. Tú:','["Don''t serve drinks meant for the cut-off guest", "Serve the friend double", "Serve if the friend tips", "Let it slide"]'::jsonb,'["No servir tragos para la persona cortada", "Servir doble al amigo", "Servir si da propina", "Dejarlo pasar"]'::jsonb,0,'Serving through a friend is still serving the intoxicated person.','Servir por medio de otro sigue siendo servirle.','https://www.revisor.mn.gov/statutes/cite/340A.502',array['bartender']::text[],'role','easy',array['intox','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','drinks','In the U.S., a standard drink has about how much pure alcohol?','En EE. UU., una bebida estándar tiene cuánto alcohol puro?','["5 grams", "30 grams", "14 grams (0.6 oz)", "50 grams"]'::jsonb,'["5 gramos", "30 gramos", "14 gramos (0.6 oz)", "50 gramos"]'::jsonb,2,'NIAAA: one standard drink = 14 g of pure alcohol.','NIAAA: una bebida estándar = 14 g de alcohol puro.','https://www.niaaa.nih.gov/alcohols-effects-health/alcohol-topics/alcohol-facts-and-statistics/what-standard-drink',array['bartender']::text[],'role','easy',array['drinks','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','drinks','Which equals about one standard drink?','¿Cuál equivale a una bebida estándar?','["A full bottle of wine", "A 24 oz craft IPA", "12 oz of regular beer (about 5%)", "A double shot"]'::jsonb,'["Una botella de vino", "Una IPA de 24 oz", "12 oz de cerveza normal (aprox. 5%)", "Un trago doble"]'::jsonb,2,'CDC: 12 oz beer at 5%, 5 oz wine at 12%, 1.5 oz spirits at 40%.','CDC: 12 oz cerveza 5%, 5 oz vino 12%, 1.5 oz destilado 40%.','https://www.cdc.gov/alcohol/standard-drink-sizes/index.html',array['bartender']::text[],'role','med',array['drinks','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','drinks','A standard pour of 80-proof liquor is:','Una porción estándar de licor de 40% es:','["1.5 oz", "0.5 oz", "6 oz", "3 oz"]'::jsonb,'["1.5 oz", "0.5 oz", "6 oz", "3 oz"]'::jsonb,0,'CDC: 1.5 oz of 40% spirits is one standard drink.','CDC: 1.5 oz de destilado 40% es una bebida estándar.','https://www.cdc.gov/alcohol/standard-drink-sizes/index.html',array['bartender']::text[],'role','med',array['drinks','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','drinks','A standard glass of wine (12%) is:','Una copa estándar de vino (12%) es:','["2 oz", "10 oz", "5 oz", "8 oz"]'::jsonb,'["2 oz", "10 oz", "5 oz", "8 oz"]'::jsonb,2,'CDC: 5 oz of 12% wine is one standard drink.','CDC: 5 oz de vino 12% es una bebida estándar.','https://www.cdc.gov/alcohol/standard-drink-sizes/index.html',array['bartender']::text[],'role','easy',array['drinks','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','drinks','Why should you know a craft beer''s alcohol content?','¿Por qué conocer el alcohol de una cerveza artesanal?','["Strong beers can equal 2 or more standard drinks", "To set the price only", "It doesn''t matter", "For the glass color"]'::jsonb,'["Las cervezas fuertes pueden ser 2 o más bebidas estándar", "Solo para el precio", "No importa", "Por el color del vaso"]'::jsonb,0,'Higher ABV and bigger pours add up fast.','Más grados y más tamaño suman rápido.','https://www.cdc.gov/alcohol/standard-drink-sizes/index.html',array['bartender']::text[],'role','med',array['drinks','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','At bar close, what should match your sales report?','Al cerrar el bar, ¿qué debe coincidir con el reporte de ventas?','["Nothing", "Cash plus card totals, after removing the starting bank", "Only the tip jar", "The number of glasses"]'::jsonb,'["Nada", "Efectivo más tarjetas, quitando el fondo inicial", "Solo el bote de propinas", "El número de vasos"]'::jsonb,1,'Over/short means something was missed or rung wrong.','Sobrante/faltante indica un error.','general hospitality best practice',array['bartender']::text[],'role','med',array['cash','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','A comp or void at the bar needs:','Una cortesía o anulación en el bar necesita:','["Nothing", "To be hidden", "A guest''s signature only", "A reason and manager approval per policy"]'::jsonb,'["Nada", "Ocultarse", "Solo firma del huésped", "Razón y aprobación del gerente según la política"]'::jsonb,3,'Approved, logged comps keep inventory and cash accurate.','Cortesías aprobadas y registradas mantienen el control.','general hospitality best practice',array['bartender']::text[],'role','med',array['cash','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','When should you ring a drink into the register?','¿Cuándo registras un trago en la caja?','["Never for regulars", "Before or as you serve it, every time", "At the end of the night", "Only for big tabs"]'::jsonb,'["Nunca a clientes frecuentes", "Antes o al servirlo, siempre", "Al final de la noche", "Solo cuentas grandes"]'::jsonb,1,'Every drink rung in keeps counts and cash matched.','Registrar todo cuadra inventario y caja.','general hospitality best practice',array['bartender']::text[],'role','easy',array['cash','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','inventory','Why do bars track pour cost or variance?','¿Por qué el bar mide costo o variación?','["To set hours", "To pick music", "To catch over-pouring, waste, or theft", "To count guests"]'::jsonb,'["Para el horario", "Para elegir música", "Para detectar porciones grandes, desperdicio o robo", "Para contar clientes"]'::jsonb,2,'Variance shows inventory that''s missing compared to sales.','La variación muestra inventario faltante vs. ventas.','general hospitality best practice',array['bartender']::text[],'role','med',array['inventory','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','inventory','Which tool helps keep pours consistent?','¿Qué ayuda a servir porciones iguales?','["A coffee mug", "A jigger or measured pour spout", "Eyeballing", "Pouring until the glass is full"]'::jsonb,'["Una taza", "Un jigger o pico medidor", "Al tanteo", "Llenar el vaso"]'::jsonb,1,'Measured pours control cost and help guests drink responsibly.','Medir controla costo y ayuda al consumo responsable.','general hospitality best practice',array['bartender']::text[],'role','easy',array['inventory','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','food_safety','A glass breaks in the ice bin. What do you do?','Se rompe un vaso en el hielo. ¿Qué haces?','["Cover it with fresh ice", "Pick out the big pieces", "Keep using it carefully", "Empty and melt all the ice, clean and sanitize the bin, then refill"]'::jsonb,'["Cubrirlo con hielo nuevo", "Sacar los pedazos grandes", "Seguir usándolo con cuidado", "Vaciar y derretir todo el hielo, limpiar y desinfectar, y rellenar"]'::jsonb,3,'Tiny glass shards can''t be seen — ''burn'' the whole bin.','No se ven los pedacitos; hay que tirar todo el hielo.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['bartender']::text[],'role','hard',array['food_safety','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','food_safety','Garnish fruit should be handled with:','La fruta para decorar se manipula con:','["The ice scoop", "Your teeth", "Bare hands", "Tongs, picks, or gloves — not bare hands"]'::jsonb,'["La pala de hielo", "Los dientes", "Mano desnuda", "Pinzas, palillos o guantes, no con la mano"]'::jsonb,3,'Food Code limits bare-hand contact with ready-to-eat food.','El código limita el contacto con alimentos listos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['bartender']::text[],'role','easy',array['food_safety','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','food_safety','How long can cut citrus garnish sit out at room temperature?','¿Cuánto puede estar fruta cortada a temperatura ambiente?','["Until it turns brown", "A week", "Follow your hotel''s time limit and discard at end of shift", "Forever"]'::jsonb,'["Hasta que se ponga café", "Una semana", "Seguir el límite del hotel y tirarla al final del turno", "Siempre"]'::jsonb,2,'Date and discard per your bar''s procedure.','Fecha y desecha según el procedimiento.','general hospitality best practice',array['bartender']::text[],'role','med',array['food_safety','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','A guest asks for a drink you don''t know how to make. Best reply?','Piden un trago que no sabes preparar. ¿Mejor respuesta?','["Ignore them", "Be honest, ask how they like it or suggest something close", "Say it doesn''t exist", "Pretend and guess"]'::jsonb,'["Ignorarlo", "Ser honesto, preguntar cómo le gusta o sugerir algo similar", "Decir que no existe", "Fingir y adivinar"]'::jsonb,1,'Honesty plus a good suggestion keeps trust.','Honestidad y una buena sugerencia generan confianza.','general hospitality best practice',array['bartender']::text[],'role','easy',array['service','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','A guest wants to start a tab. What do you hold?','Alguien quiere abrir una cuenta. ¿Qué guardas?','["Follow policy: pre-authorize a card or charge to the room after verifying the guest", "Their car keys", "Their phone", "Nothing"]'::jsonb,'["Según la política: preautorizar tarjeta o cargar al cuarto verificando al huésped", "Sus llaves", "Su teléfono", "Nada"]'::jsonb,0,'Verified tabs prevent walkouts.','Las cuentas verificadas evitan que se vayan sin pagar.','general hospitality best practice',array['bartender']::text[],'role','med',array['service','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','A guest asks you to charge drinks to room 214. What do you check?','Piden cargar tragos al cuarto 214. ¿Qué verificas?','["Only the room number", "Name and room match the registered guest (key or ID)", "Nothing", "Their age only"]'::jsonb,'["Solo el número", "Que nombre y cuarto coincidan con el huésped registrado (llave o ID)", "Nada", "Solo la edad"]'::jsonb,1,'Prevents charging the wrong guest.','Evita cargar al huésped equivocado.','general hospitality best practice',array['bartender']::text[],'role','med',array['service','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','A guest who''s been drinking wants to drive. Best response?','Alguien que ha tomado quiere manejar. ¿Mejor respuesta?','["Offer a rideshare, taxi, or remind them their room is upstairs", "Serve one more for the road", "Ignore it", "Give them coffee and send them off"]'::jsonb,'["Ofrecer taxi o app, o recordarle que su cuarto está arriba", "Servir uno más", "Ignorarlo", "Darle café y despedirlo"]'::jsonb,0,'Coffee doesn''t sober people up; only time does.','El café no quita lo borracho; solo el tiempo.','https://www.nhtsa.gov/road-safety',array['bartender']::text[],'role','easy',array['safety','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','A fight starts at the bar. What do you do?','Empieza una pelea en el bar. ¿Qué haces?','["Keep serving", "Jump in to separate them", "Stay out of it physically, call the manager and 911 if needed", "Film it"]'::jsonb,'["Seguir sirviendo", "Meterte a separarlos", "No meterte físicamente, llamar al gerente y al 911 si hace falta", "Grabarlo"]'::jsonb,2,'Your safety first; let police handle violence.','Primero tu seguridad; la policía maneja la violencia.','general hospitality best practice',array['bartender']::text[],'role','med',array['safety','bartender']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','brand_std','A Hampton guest isn''t happy with their stay. What does the 100% Hampton Guarantee tell team members to do?','Un huésped de Hampton no está contento. ¿Qué dice la Garantía 100% Hampton?','["Send them to corporate", "Make it right — any team member can help improve the stay", "Nothing unless they paid cash", "Only the GM can listen"]'::jsonb,'["Mandarlo a corporativo", "Arreglarlo: cualquier miembro del equipo puede mejorar la estancia", "Nada salvo si pagó en efectivo", "Solo el gerente escucha"]'::jsonb,1,'Hampton: ''talk to any member of our team and we''ll Make It Right. Guaranteed.'' Follow your GM''s guarantee procedure for refunds.','Hampton: ''habla con cualquiera del equipo y lo arreglaremos''. Sigue el procedimiento del gerente para reembolsos.','https://www.hilton.com/en/brands/hampton-by-hilton/',array['front_desk','night_audit']::text[],'role','easy',array['hotel','brand_std','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','brand_std','What signature item does Hampton''s free hot breakfast feature?','¿Qué platillo distintivo tiene el desayuno gratis de Hampton?','["Crepes only", "Waffles", "Sushi", "Steak"]'::jsonb,'["Solo crepas", "Waffles", "Sushi", "Carne"]'::jsonb,1,'Hampton''s brand page: ''Waffles, of course.''','Página de Hampton: ''Waffles, por supuesto''.','https://www.hilton.com/en/brands/hampton-by-hilton/',array['front_desk','night_audit']::text[],'role','easy',array['hotel','brand_std','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','brand_std','Which Hilton Honors member benefit is listed for our Hampton?','¿Qué beneficio de Hilton Honors aparece para nuestro Hampton?','["Free spa", "Free minibar", "Free valet", "Digital Check-In and Choose Your Room"]'::jsonb,'["Spa gratis", "Minibar gratis", "Valet gratis", "Check-in digital y elegir cuarto"]'::jsonb,3,'Hilton lists Honors discount rate, points, Choose Your Room, Digital Check-In and Digital Key for this hotel.','Hilton enumera tarifa Honors, puntos, elegir cuarto, check-in y llave digital.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','night_audit']::text[],'role','med',array['hotel','brand_std','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','shuttle','How does Hilton describe our Hampton''s airport shuttle?','¿Cómo describe Hilton el shuttle al aeropuerto de nuestro Hampton?','["Weekends only", "Complimentary 24-hour courtesy shuttle", "Paid, daytime only", "No shuttle"]'::jsonb,'["Solo fines de semana", "Shuttle de cortesía gratis las 24 horas", "Pagado, solo de día", "No hay shuttle"]'::jsonb,1,'Hotel page: ''24 hour courtesy shuttle'', complimentary.','Página del hotel: shuttle de cortesía 24 horas, gratis.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','night_audit']::text[],'role','easy',array['hotel','shuttle','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','meetings','Up to how many people does our Hampton list for its meeting space?','¿Para cuántas personas máximo es la sala de juntas de nuestro Hampton?','["35", "250", "10", "100"]'::jsonb,'["35", "250", "10", "100"]'::jsonb,0,'Hilton: ''Find and book meeting space for up to 35 people.''','Hilton: espacio para hasta 35 personas.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','night_audit']::text[],'role','med',array['hotel','meetings','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','brand_std','What does the SpringHill Lounge offer, per Marriott?','¿Qué ofrece el SpringHill Lounge según Marriott?','["Full steakhouse menu", "Room service only", "Handpicked wines, local craft beers, sodas and pizza", "Only coffee"]'::jsonb,'["Menú completo de carnes", "Solo servicio a cuartos", "Vinos seleccionados, cervezas artesanales locales, refrescos y pizza", "Solo café"]'::jsonb,2,'Marriott hotel page describes the SpringHill Lounge this way.','Así lo describe la página de Marriott.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['bartender','front_desk','night_audit']::text[],'role','easy',array['hotel','brand_std','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','brand_std','Which room feature does Marriott list in EVERY suite at our SpringHill?','¿Qué tiene CADA suite de nuestro SpringHill según Marriott?','["Microwave, refrigerator, sofa bed and wet bar", "Kitchen with stove", "Balcony", "Hot tub"]'::jsonb,'["Microondas, refrigerador, sofá cama y wet bar", "Cocina con estufa", "Balcón", "Jacuzzi"]'::jsonb,0,'Marriott: ''microwave, refrigerator, sofa bed, and wet bar in every room.''','Marriott: en cada cuarto.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','night_audit']::text[],'role','med',array['hotel','brand_std','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','brand_std','Which digital feature can Marriott Bonvoy guests use at our SpringHill?','¿Qué función digital pueden usar los socios Bonvoy en nuestro SpringHill?','["Robot butler", "Text-to-pay minibar", "Mobile Key", "Face scan entry"]'::jsonb,'["Mayordomo robot", "Minibar por texto", "Llave móvil", "Entrada con rostro"]'::jsonb,2,'Mobile Key is listed among the hotel''s amenities.','La llave móvil aparece en los servicios.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','night_audit']::text[],'role','easy',array['hotel','brand_std','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','accessibility','Per Marriott, what''s our SpringHill''s rule for service animals?','Según Marriott, ¿regla de nuestro SpringHill para animales de servicio?','["Allowed with a $75 fee", "Welcome without a fee or documentation", "Need a certificate", "Not allowed, like pets"]'::jsonb,'["Con cuota de $75", "Bienvenidos sin cuota ni documentos", "Con certificado", "No permitidos como mascotas"]'::jsonb,1,'Marriott lists ''Service Animals are welcome without a fee or documentation'' — matching the ADA.','Marriott lo indica, igual que la ADA.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','night_audit']::text[],'role','med',array['hotel','accessibility','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','parking','A SpringHill guest wants to park in the underground garage. What does Marriott say?','Un huésped quiere estacionarse en el subterráneo. ¿Qué dice Marriott?','["Valet only", "It''s subject to availability; one vehicle max per room", "Closed in winter", "Guaranteed for everyone"]'::jsonb,'["Solo valet", "Sujeto a disponibilidad; un vehículo máximo", "Cerrado en invierno", "Garantizado para todos"]'::jsonb,1,'Marriott: ''1 vehicle max… Underground parking subject to availability.''','Marriott: 1 vehículo, subterráneo según disponibilidad.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','night_audit']::text[],'role','med',array['hotel','parking','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','brand_std','Which perk does IHG list for families at our Holiday Inn Express?','¿Qué beneficio lista IHG para familias en nuestro Holiday Inn Express?','["Free theme park tickets", "Free babysitting", "Kids eat free", "Free rental car"]'::jsonb,'["Boletos gratis", "Niñera gratis", "Niños comen gratis", "Auto gratis"]'::jsonb,2,'IHG hotel page lists ''Kids eat free.''','La página de IHG lo indica.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','night_audit']::text[],'role','easy',array['hotel','brand_std','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','brand_std','What kind of coffee machine does our Holiday Inn Express have in the lobby 24/7?','¿Qué cafetera hay en el lobby 24/7 en nuestro Holiday Inn Express?','["Bean-to-cup", "None after 10 p.m.", "Drip pot only", "Instant coffee"]'::jsonb,'["De grano a taza", "Ninguna después de las 10 p.m.", "Solo de goteo", "Café instantáneo"]'::jsonb,0,'IHG: new bean-to-cup coffee machine available 24/7 in the lobby.','IHG: máquina de grano a taza 24/7.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','night_audit']::text[],'role','med',array['hotel','brand_std','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','groups','Which nearby rinks does IHG name for youth hockey teams staying with us?','¿Qué pistas cercanas menciona IHG para equipos juveniles?','["Mall of America rink", "Xcel Energy Center only", "Plymouth Ice Center and Braemar Arena", "None"]'::jsonb,'["Pista del Mall of America", "Solo Xcel Energy Center", "Plymouth Ice Center y Braemar Arena", "Ninguna"]'::jsonb,2,'IHG lists Plymouth Ice Center (8.8 mi), Braemar Arena (10.7 mi) and the NSC Super Rink.','IHG menciona Plymouth, Braemar y el Super Rink.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','night_audit']::text[],'role','med',array['hotel','groups','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','A family asks about Valleyfair from our Golden Valley hotel. What do you tell them?','Una familia pregunta por Valleyfair desde Golden Valley. ¿Qué les dices?','["It''s walking distance", "It''s inside Mall of America", "It''s in Shakopee, about 20 miles away — they''ll need a car or rideshare", "It''s in downtown St. Paul"]'::jsonb,'["Se llega caminando", "Está en el Mall of America", "Está en Shakopee, a unas 20 millas; necesitan auto o app", "Está en St. Paul"]'::jsonb,2,'Valleyfair: 1 Valleyfair Dr., Shakopee; IHG lists it ~20 miles away. Check its site for seasonal hours.','Valleyfair está en Shakopee; revisa horarios por temporada.','https://www.valleyfair.com/',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','A guest asks about the Spoonbridge and Cherry. Where is it and what does it cost?','Preguntan por la ''Cuchara y Cereza''. ¿Dónde está y cuánto cuesta?','["Minneapolis Sculpture Garden by the Walker — free, 6 a.m. to midnight", "St. Paul — closed in winter", "Mall of America — $20", "Bloomington — tickets required"]'::jsonb,'["En el Jardín de Esculturas junto al Walker; gratis, 6 a.m. a medianoche", "En St. Paul; cerrado en invierno", "En el Mall of America; $20", "En Bloomington; con boleto"]'::jsonb,0,'Walker: the garden is free and open 6 a.m.–midnight every day, all year.','Walker: gratis, 6 a.m.–medianoche todo el año.','https://walkerart.org/visit/garden',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','A guest wants to see a waterfall near the airport. Where do you send them?','Un huésped quiere ver una cascada cerca del aeropuerto. ¿A dónde?','["Valleyfair", "Como Zoo", "Minnehaha Falls in Minnehaha Regional Park, Minneapolis", "Mall of America"]'::jsonb,'["Valleyfair", "Como Zoo", "Minnehaha Falls, en Minnehaha Regional Park, Minneapolis", "Mall of America"]'::jsonb,2,'Minnehaha Regional Park, 4801 S Minnehaha Dr. Developed areas are open 6 a.m.–midnight.','Minnehaha Regional Park, 4801 S Minnehaha Dr.; 6 a.m.–medianoche.','https://www.minneapolisparks.org/parks-destinations/parks-lakes/minnehaha_regional_park/',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest wants to see a waterfall near the airport. Where do you send them?','Un huésped quiere ver una cascada cerca del aeropuerto. ¿A dónde?','["Como Zoo", "Mall of America", "Valleyfair", "Minnehaha Falls in Minnehaha Regional Park, Minneapolis"]'::jsonb,'["Como Zoo", "Mall of America", "Valleyfair", "Minnehaha Falls, en Minnehaha Regional Park, Minneapolis"]'::jsonb,3,'Minnehaha Regional Park, 4801 S Minnehaha Dr. Developed areas are open 6 a.m.–midnight.','Minnehaha Regional Park, 4801 S Minnehaha Dr.; 6 a.m.–medianoche.','https://www.minneapolisparks.org/parks-destinations/parks-lakes/minnehaha_regional_park/',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','Until what time are the developed areas of Minnehaha Park open?','¿Hasta qué hora abren las áreas desarrolladas del parque Minnehaha?','["8 p.m.", "Midnight", "24 hours", "Sunset"]'::jsonb,'["8 p.m.", "Medianoche", "24 horas", "El atardecer"]'::jsonb,1,'MPRB: 6 a.m.–midnight in developed areas; 6 a.m.–10 p.m. in undeveloped areas.','MPRB: 6 a.m.–medianoche.','https://www.minneapolisparks.org/parks-destinations/parks-lakes/minnehaha_regional_park/',array['front_desk','night_audit']::text[],'role','easy',array['hotel','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
