insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','A guest asks where Como Zoo & Conservatory is.','Preguntan dónde está el Como Zoo & Conservatory.','["St. Paul (1225 Estabrook Dr.)", "Golden Valley", "Shakopee", "Bloomington, next to MOA"]'::jsonb,'["St. Paul (1225 Estabrook Dr.)", "Golden Valley", "Shakopee", "Bloomington, junto al MOA"]'::jsonb,0,'Como Zoo & Conservatory: 1225 Estabrook Drive, St. Paul. 24-hr info line 651-487-8200.','Como Zoo: 1225 Estabrook Dr., St. Paul.','https://comozooconservatory.org/visit/',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
