insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','Bar guests ask how to see the Spoonbridge and Cherry. What''s true?','En el bar preguntan por la ''Cuchara y Cereza''. ¿Qué es cierto?','["It''s in the free Minneapolis Sculpture Garden, open 6 a.m.–midnight", "It''s inside the Mall of America", "It costs $25", "It''s only open in summer"]'::jsonb,'["Está en el Jardín de Esculturas gratis, 6 a.m.–medianoche", "Está en el Mall of America", "Cuesta $25", "Solo abre en verano"]'::jsonb,0,'Walker: always free, open daily 6 a.m.–midnight, all year.','Walker: siempre gratis, todo el año.','https://walkerart.org/visit/garden',array['bartender','front_desk','night_audit']::text[],'role','med',array['hotel','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
